solution.code:
function App() {
  const id = useId();
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <label htmlFor={id} style={{ display: 'block', marginBottom: 4 }}>Username</label>
      <input id={id} type="text" aria-describedby={`${id}-help`} />
      <p id={`${id}-help`} style={{ color: '#666' }}>Choose a public display name.</p>
    </div>
  );
}
